public class Main {
    // Generic class
    static class Box<T> {
        private T value;
        public Box(T value) { this.value = value; }
        public T getValue() { return value; }
        public void setValue(T value) { this.value = value; }
    }

    // Generic method
    static <T> void printArray(T[] array) {
        for (T item : array) {
            System.out.print(item + " ");
        }
        System.out.println();
    }

    // Bounded type parameter
    static <T extends Comparable<T>> T findMax(T a, T b) {
        return a.compareTo(b) > 0 ? a : b;
    }

    public static void main(String[] args) {
        Box<Integer> intBox = new Box<>(42);
        Box<String> strBox = new Box<>("Hello Generics");

        System.out.println("Integer box: " + intBox.getValue());
        System.out.println("String box: " + strBox.getValue());

        Integer[] nums = {1, 2, 3, 4, 5};
        String[] words = {"a", "b", "c"};
        printArray(nums);
        printArray(words);

        System.out.println("Max of 10 and 20: " + findMax(10, 20));
        System.out.println("Max of Apple and Banana: " + findMax("Apple", "Banana"));
    }
}
